<?php require_once __DIR__.'/includes/bootstrap.php';$token=(string)($_GET['token']??'');$s=$pdo->prepare('SELECT s.*,a.title,a.artist,a.description,a.cover_file FROM shares s JOIN albums a ON a.id=s.album_id WHERE s.token=?');$s->execute([$token]);$share=$s->fetch();if(!$share||($share['expires_at']&&strtotime($share['expires_at'])<time())){http_response_code(404);render_header('Nicht verfügbar');echo '<div class="alert alert-warning">Dieser Freigabelink ist ungültig oder abgelaufen.</div>';render_footer();exit;}if($share['password_hash']&&!($_SESSION['share_ok_'.$share['id']]??false)){if($_SERVER['REQUEST_METHOD']==='POST'&&password_verify($_POST['password']??'',$share['password_hash'])){$_SESSION['share_ok_'.$share['id']]=true;header('Location: '.$_SERVER['REQUEST_URI']);exit;}render_header('Geschützte Freigabe');echo '<div class="row justify-content-center"><div class="col-md-5"><div class="card shadow-sm"><div class="card-body"><h1 class="h4">Passwort erforderlich</h1><form method="post"><input type="password" class="form-control my-3" name="password" required><button class="btn btn-primary">Album öffnen</button></form></div></div></div></div>';render_footer();exit;}$s=$pdo->prepare('SELECT * FROM tracks WHERE album_id=? ORDER BY track_no,id');$s->execute([$share['album_id']]);$tracks=$s->fetchAll();render_header($share['title']);?><div class="row g-5 align-items-start"><div class="col-md-4"><?php if($share['cover_file']):?><img class="album-cover shadow" src="<?=base_url('uploads/covers/'.$share['cover_file'])?>" alt="Cover"><?php else:?><div class="cover-placeholder shadow">♪</div><?php endif?></div><div class="col-md-8"><p class="text-uppercase text-body-secondary small mb-1">Album</p><h1 class="display-5 fw-bold"><?=e($share['title'])?></h1><p class="lead"><?=e($share['artist'])?></p><?php if($share['description']):?><p class="text-body-secondary"><?=nl2br(e($share['description']))?></p><?php endif?><?php if($share['allow_download']):?><a class="btn btn-primary mb-4" href="download_album.php?token=<?=e($token)?>">Ganzes Album herunterladen</a><?php endif?><div class="list-group shadow-sm"><?php foreach($tracks as $i=>$t):?><div class="list-group-item track-row d-flex align-items-center gap-3"><button class="btn btn-sm btn-outline-primary rounded-circle" data-play data-src="<?=base_url('stream.php?token='.urlencode($token).'&track='.$t['id'])?>" data-title="<?=e($t['title'])?>">▶</button><div class="flex-grow-1"><div class="fw-semibold"><?=e($t['title'])?></div><div class="small text-body-secondary"><?=number_format($t['file_size']/1048576,1,',','.')?> MB</div></div><?php if($share['allow_download']):?><a class="btn btn-sm btn-outline-secondary" href="download_track.php?token=<?=e($token)?>&track=<?=$t['id']?>">Download</a><?php endif?></div><?php endforeach?><?php if(!$tracks):?><div class="list-group-item">Noch keine Titel vorhanden.</div><?php endif?></div></div></div><div class="audio-player bg-body border rounded-3 shadow-lg p-3 mt-5"><div id="nowPlaying" class="small fw-semibold mb-2">Titel auswählen</div><audio id="mainPlayer" controls class="w-100"></audio></div><?php render_footer();
